document.addEventListener("DOMContentLoaded",async()=>{const l=document.getElementById("sd-server-loader"),c=document.getElementById("sd-server-content"),m="/api/server/fivem-detail.php";try{const i=await(await fetch(m)).json();if(i.Data){const e=i.Data;e.vars&&e.vars.banner_detail?document.getElementById("fm-banner").src=e.vars.banner_detail:document.getElementById("fm-banner").style.display="none",document.getElementById("fm-icon").src="/assets/server-logo.jpg";const u=e.hostname||"South District RP";document.getElementById("fm-title").textContent=u.replace(/\^([0-9]|\*|_|r)/g,"");const p=e.vars&&e.vars.ProjectDesc?e.vars.ProjectDesc:"Serveur GTA V Roleplay";document.getElementById("fm-subtitle").textContent=p,document.getElementById("fm-players").textContent=`${e.clients||0}/${e.sv_maxclients||0}`;const f=document.getElementById("fm-details-list");e.vars&&["Boutique","Createur","Discord","Développement","EquipeTechnique","Graphiste","Illégal","Légal","Mentalité","Staff"].forEach(t=>{if(e.vars[t]){const s=document.createElement("div");s.className="fm-detail-row";let d=e.vars[t];(t==="Boutique"||t==="Discord")&&(d=`<a href="https://${e.vars[t].replace("https://","")}" target="_blank">${e.vars[t]}</a>`),s.innerHTML=`<span class="fm-detail-label">${t}:</span> <span class="fm-detail-value">${d}</span>`,f.appendChild(s)}});const g=document.getElementById("fm-tags");e.vars&&e.vars.tags&&e.vars.tags.split(",").forEach(t=>{const s=document.createElement("span");s.className="fm-tag",s.textContent=t.trim(),g.appendChild(s)});const v=document.getElementById("fm-resources");e.resources&&(document.getElementById("fm-resources-count").textContent=e.resources.length,e.resources.forEach(r=>{const t=document.createElement("span");t.className="fm-resource-item",t.textContent=r,v.appendChild(t)}))}}catch(n){console.error(n),document.getElementById("fm-title").textContent="Erreur API"}finally{l&&c&&(l.style.display="none",c.style.display="grid")}const a=document.getElementById("btn-copy-url");a&&a.addEventListener("click",()=>{navigator.clipboard.writeText("leepglo");const n=a.innerHTML;a.textContent="Copié !",setTimeout(()=>{a.innerHTML=n},2e3)});const o=document.getElementById("btn-show-all");o&&o.addEventListener("click",()=>{const n=document.getElementById("fm-resources");n.style.maxHeight==="none"?(n.style.maxHeight="80px",o.textContent="Show all"):(n.style.maxHeight="none",o.textContent="Hide")})});
